def find_permutation(n, k):
    if k == 0:
        if n == 1:
            return [1]
        else:
            return -1
    if k > n // 2:
        return -1
    if n == 2 and k == 1:
        return -1
    if n == 2 and k == 0:
        return [1, 2]

    # Create a base permutation where the first k elements are in place
    permutation = list(range(1, k + 1)) + list(range(n, n - k, -1))
    # Fill the rest of the permutation with the remaining numbers
    remaining = [i for i in range(1, n + 1) if i not in permutation]
    permutation = permutation + remaining[k:]
    return permutation

